CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS golfers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS schedule_defaults (id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1), monday BOOLEAN NOT NULL DEFAULT TRUE, tuesday BOOLEAN NOT NULL DEFAULT TRUE, wednesday BOOLEAN NOT NULL DEFAULT FALSE, thursday BOOLEAN NOT NULL DEFAULT FALSE, friday BOOLEAN NOT NULL DEFAULT FALSE, saturday BOOLEAN NOT NULL DEFAULT TRUE, sunday BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO schedule_defaults (id) VALUES (1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS weekly_overrides (week_start DATE PRIMARY KEY, monday BOOLEAN NOT NULL, tuesday BOOLEAN NOT NULL, wednesday BOOLEAN NOT NULL, thursday BOOLEAN NOT NULL, friday BOOLEAN NOT NULL, saturday BOOLEAN NOT NULL, sunday BOOLEAN NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS invitations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), golfer_id UUID NOT NULL REFERENCES golfers(id), week_start DATE NOT NULL, token TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, sent_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (golfer_id, week_start));
CREATE TABLE IF NOT EXISTS booking_dates (invitation_id UUID NOT NULL REFERENCES invitations(id) ON DELETE CASCADE, play_date DATE NOT NULL, PRIMARY KEY (invitation_id, play_date));
CREATE TABLE IF NOT EXISTS email_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email_key TEXT NOT NULL UNIQUE, invitation_id UUID REFERENCES invitations(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('invitation', 'reminder')), play_date DATE, sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
